1	/*
2	 * Pure expense logic: no DOM, no localStorage, no clock, no randomness.
3	 * Every function returns a new value and never mutates its inputs,
4	 * so this file can be loaded in the browser or required from Node tests.
5	 */
6	(function (root) {
7	  "use strict";
8	
9	  var CATEGORIES = ["Food", "Transport", "Bills", "Fun", "Other"];
10	
11	  var ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
12	
13	  /** Convert an amount (number or numeric string) to integer cents, or NaN. */
14	  function toCents(amount) {
15	    var n = typeof amount === "string" ? Number(amount.trim()) : amount;
16	    if (typeof n !== "number" || !isFinite(n) || (typeof amount === "string" && amount.trim() === "")) {
17	      return NaN;
18	    }
19	    // Shift the decimal point in the number's text form, so 1.005 becomes
20	    // 100.5 (and rounds to 101) instead of 100.49999… from n * 100.
21	    var s = String(n);
22	    return s.indexOf("e") === -1 ? Math.round(Number(s + "e2")) : Math.round(n * 100);
23	  }
24	
25	  /** True if `str` is a real calendar date in YYYY-MM-DD form. */
26	  function isValidDate(str) {
27	    if (typeof str !== "string" || !ISO_DATE.test(str)) return false;
28	    var parts = str.split("-").map(Number);
29	    var d = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
30	    return (
31	      d.getUTCFullYear() === parts[0] &&
32	      d.getUTCMonth() === parts[1] - 1 &&
33	      d.getUTCDate() === parts[2]
34	    );
35	  }
36	
37	  /**
38	   * Check raw form input. Returns an object of field -> message.
39	   * An empty object means the input is valid.
40	   */
41	  function validateExpense(input) {
42	    var errors = {};
43	    input = input || {};
44	
45	    var cents = toCents(input.amount);
46	    if (isNaN(cents)) {
47	      errors.amount = "Enter an amount.";
48	    } else if (cents <= 0) {
49	      errors.amount = "Amount must be greater than 0.";
50	    }
51	
52	    if (CATEGORIES.indexOf(input.category) === -1) {
53	      errors.category = "Choose a category.";
54	    }
55	
56	    if (!isValidDate(input.date)) {
57	      errors.date = "Enter a valid date.";
58	    }
59	
60	    if (input.note != null && typeof input.note !== "string") {
61	      errors.note = "Note must be text.";
62	    }
63	
64	    return errors;
65	  }
66	
67	  /**
68	   * Build a normalised expense record from raw input.
69	   * `id` and `createdAt` are passed in (rather than generated here) to keep
70	   * this function pure. Throws if the input is invalid.
71	   */
72	  function createExpense(input, id, createdAt) {
73	    var errors = validateExpense(input);
74	    var fields = Object.keys(errors);
75	    if (fields.length > 0) {
76	      throw new Error("Invalid expense: " + fields.map(function (f) { return errors[f]; }).join(" "));
77	    }
78	    return {
79	      id: String(id),
80	      amount: toCents(input.amount) / 100,
81	      category: input.category,
82	      date: input.date,
83	      note: (input.note || "").trim(),
84	      createdAt: Number(createdAt) || 0
85	    };
86	  }
87	
88	  /** Sum of all expense amounts, computed in cents to avoid float drift. */
89	  function calculateTotal(expenses) {
90	    var cents = (expenses || []).reduce(function (sum, e) {
91	      var c = toCents(e && e.amount);
92	      return isNaN(c) ? sum : sum + c;
93	    }, 0);
94	    return cents / 100;
95	  }
96	
97	  /**
98	   * Newest first: later `date` first; for the same date, the one added
99	   * later (`createdAt`) comes first. Returns a new array.
100	   */
101	  function sortNewestFirst(expenses) {
102	    return (expenses || []).slice().sort(function (a, b) {
103	      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
104	      return (b.createdAt || 0) - (a.createdAt || 0);
105	    });
106	  }
107	
108	  /** Return a new array with `expense` appended. */
109	  function addExpense(expenses, expense) {
110	    return (expenses || []).concat([expense]);
111	  }
112	
113	  /** Format a number as money with two decimals, e.g. 1234.5 -> "1,234.50". */
114	  function formatAmount(amount) {
115	    var cents = toCents(amount);
116	    if (isNaN(cents)) cents = 0;
117	    var negative = cents < 0;
118	    cents = Math.abs(cents);
119	    var whole = String(Math.floor(cents / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
120	    var frac = String(cents % 100).padStart(2, "0");
121	    return (negative ? "-" : "") + whole + "." + frac;
122	  }
123	
124	  /** Format a Date as local YYYY-MM-DD (for the date input default). */
125	  function toISODate(date) {
126	    var y = date.getFullYear();
127	    var m = String(date.getMonth() + 1).padStart(2, "0");
128	    var d = String(date.getDate()).padStart(2, "0");
129	    return y + "-" + m + "-" + d;
130	  }
131	
132	  /**
133	   * Turn whatever was stored (possibly corrupt) into a clean array of
134	   * valid expenses. Invalid entries are dropped.
135	   */
136	  function parseStoredExpenses(json) {
137	    var data;
138	    try {
139	      data = JSON.parse(json);
140	    } catch (e) {
141	      return [];
142	    }
143	    if (!Array.isArray(data)) return [];
144	    return data.filter(function (e) {
145	      return e && typeof e === "object" && e.id != null &&
146	        Object.keys(validateExpense(e)).length === 0;
147	    }).map(function (e) {
148	      return createExpense(e, e.id, e.createdAt);
149	    });
150	  }
151	
152	  // ---- Monthly summary ----------------------------------------------------
153	
154	  var ISO_MONTH = /^\d{4}-(0[1-9]|1[0-2])$/;
155	
156	  /** True if `str` is a month in YYYY-MM form. */
157	  function isValidMonth(str) {
158	    return typeof str === "string" && ISO_MONTH.test(str);
159	  }
160	
161	  /** "2026-11-22" -> "2026-11". */
162	  function monthOf(isoDate) {
163	    return String(isoDate).slice(0, 7);
164	  }
165	
166	  /** Move a YYYY-MM month by `delta` months, e.g. ("2026-01", -1) -> "2025-12". */
167	  function shiftMonth(month, delta) {
168	    var parts = month.split("-").map(Number);
169	    var index = parts[0] * 12 + (parts[1] - 1) + delta;
170	    var y = Math.floor(index / 12);
171	    var m = index - y * 12 + 1;
172	    return String(y).padStart(4, "0") + "-" + String(m).padStart(2, "0");
173	  }
174	
175	  /** Expenses whose date falls in the given YYYY-MM month. Returns a new array. */
176	  function filterByMonth(expenses, month) {
177	    return (expenses || []).filter(function (e) {
178	      return e && monthOf(e.date) === month;
179	    });
180	  }
181	
182	  /**
183	   * Totals per category for one month.
184	   * Every category is always present, in CATEGORIES order (so the chart's
185	   * rows don't jump around between months). `share` is the fraction of the
186	   * month's total (0..1); `ofMax` is the fraction of the largest category,
187	   * which is what a bar's length is drawn against.
188	   */
189	  function summarizeMonth(expenses, month) {
190	    var inMonth = filterByMonth(expenses, month);
191	    var centsByCat = {};
192	    var countByCat = {};
193	    CATEGORIES.forEach(function (c) { centsByCat[c] = 0; countByCat[c] = 0; });
194	
195	    inMonth.forEach(function (e) {
196	      var c = toCents(e.amount);
197	      if (!isNaN(c) && Object.prototype.hasOwnProperty.call(centsByCat, e.category)) {
198	        centsByCat[e.category] += c;
199	        countByCat[e.category] += 1;
200	      }
201	    });
202	
203	    var totalCents = 0;
204	    var maxCents = 0;
205	    CATEGORIES.forEach(function (c) {
206	      totalCents += centsByCat[c];
207	      if (centsByCat[c] > maxCents) maxCents = centsByCat[c];
208	    });
209	
210	    return {
211	      month: month,
212	      count: inMonth.length,
213	      total: totalCents / 100,
214	      categories: CATEGORIES.map(function (c) {
215	        return {
216	          category: c,
217	          total: centsByCat[c] / 100,
218	          count: countByCat[c],
219	          share: totalCents ? centsByCat[c] / totalCents : 0,
220	          ofMax: maxCents ? centsByCat[c] / maxCents : 0
221	        };
222	      })
223	    };
224	  }
225	
226	  // ---- Import merge -------------------------------------------------------
227	
228	  /** What makes two expenses "the same" for import: date, category, amount, note. */
229	  function expenseKey(e) {
230	    return [e.date, e.category, toCents(e.amount), (e.note || "").trim()].join("\u0000");
231	  }
232	
233	  /**
234	   * Add `incoming` expenses to `existing`, skipping ones already present.
235	   * Matching counts copies: if `existing` has one "coffee 3.00 on May 1"
236	   * and `incoming` has two, one is skipped and one is added. So
237	   * re-importing an export adds nothing, but genuine repeats are kept.
238	   * Returns { expenses, added, skipped } (new arrays; inputs untouched).
239	   */
240	  function mergeExpenses(existing, incoming) {
241	    var counts = {};
242	    (existing || []).forEach(function (e) {
243	      var k = expenseKey(e);
244	      counts[k] = (counts[k] || 0) + 1;
245	    });
246	
247	    var added = [];
248	    var skipped = [];
249	    (incoming || []).forEach(function (e) {
250	      var k = expenseKey(e);
251	      if (counts[k] > 0) {
252	        counts[k] -= 1;
253	        skipped.push(e);
254	      } else {
255	        added.push(e);
256	      }
257	    });
258	
259	    return {
260	      expenses: (existing || []).concat(added),
261	      added: added,
262	      skipped: skipped
263	    };
264	  }
265	
266	  var api = {
267	    CATEGORIES: CATEGORIES,
268	    mergeExpenses: mergeExpenses,
269	    isValidMonth: isValidMonth,
270	    monthOf: monthOf,
271	    shiftMonth: shiftMonth,
272	    filterByMonth: filterByMonth,
273	    summarizeMonth: summarizeMonth,
274	    toCents: toCents,
275	    isValidDate: isValidDate,
276	    validateExpense: validateExpense,
277	    createExpense: createExpense,
278	    calculateTotal: calculateTotal,
279	    sortNewestFirst: sortNewestFirst,
280	    addExpense: addExpense,
281	    formatAmount: formatAmount,
282	    toISODate: toISODate,
283	    parseStoredExpenses: parseStoredExpenses
284	  };
285	
286	  if (typeof module !== "undefined" && module.exports) {
287	    module.exports = api;
288	  } else {
289	    root.ExpenseLogic = api;
290	  }
291	})(typeof globalThis !== "undefined" ? globalThis : this);
