1	/*
2	 * Pure CSV reading and writing: no DOM, no files, no localStorage.
3	 *
4	 * Low level:  parseCSV(text) -> rows,  stringifyCSV(rows) -> text   (RFC 4180)
5	 * Expenses:   expensesToCSV(expenses) -> text
6	 *             csvToExpenses(text) -> { expenses, errors, rowCount }
7	 *
8	 * Loads in the browser (window.ExpenseCSV, after logic.js) or from Node.
9	 */
10	(function (root, factory) {
11	  "use strict";
12	  if (typeof module !== "undefined" && module.exports) {
13	    module.exports = factory(require("./logic.js"));
14	  } else {
15	    root.ExpenseCSV = factory(root.ExpenseLogic);
16	  }
17	})(typeof globalThis !== "undefined" ? globalThis : this, function (L) {
18	  "use strict";
19	
20	  var HEADER = ["date", "category", "amount", "note"];
21	  var REQUIRED = ["date", "category", "amount"];
22	
23	  // ---- Low-level CSV ------------------------------------------------------
24	
25	  /**
26	   * Parse CSV text into records: [{ fields: [...], line: n }], where `line`
27	   * is the 1-based line the record starts on (records can span lines when a
28	   * quoted field contains a newline).
29	   *
30	   * Handles: quoted fields, commas and newlines inside quotes, "" as an
31	   * escaped quote, LF / CRLF / CR line endings, a UTF-8 BOM, and a missing
32	   * or present trailing newline. A stray quote inside an unquoted field is
33	   * kept as a literal character. An unclosed quote throws.
34	   */
35	  function parseCSVRecords(text) {
36	    if (typeof text !== "string") throw new TypeError("CSV input must be a string");
37	    if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
38	
39	    var records = [];
40	    var fields = [];
41	    var field = "";
42	    var inQuotes = false;
43	    var wasQuoted = false;   // current field started with a quote
44	    var line = 1;
45	    var recordLine = 1;
46	    var quoteLine = 1;
47	    var i = 0;
48	    var n = text.length;
49	
50	    function endField() {
51	      fields.push(field);
52	      field = "";
53	      wasQuoted = false;
54	    }
55	
56	    function endRecord() {
57	      endField();
58	      records.push({ fields: fields, line: recordLine });
59	      fields = [];
60	    }
61	
62	    while (i < n) {
63	      var ch = text[i];
64	
65	      if (inQuotes) {
66	        if (ch === '"') {
67	          if (text[i + 1] === '"') {
68	            field += '"';
69	            i += 2;
70	            continue;
71	          }
72	          inQuotes = false;
73	          i += 1;
74	          continue;
75	        }
76	        if (ch === "\r" || ch === "\n") {
77	          // Keep the newline as written, but normalise CRLF to one step.
78	          if (ch === "\r" && text[i + 1] === "\n") {
79	            field += "\r\n";
80	            i += 2;
81	          } else {
82	            field += ch;
83	            i += 1;
84	          }
85	          line += 1;
86	          continue;
87	        }
88	        field += ch;
89	        i += 1;
90	        continue;
91	      }
92	
93	      if (ch === ",") {
94	        endField();
95	        i += 1;
96	      } else if (ch === "\r" || ch === "\n") {
97	        endRecord();
98	        i += ch === "\r" && text[i + 1] === "\n" ? 2 : 1;
99	        line += 1;
100	        recordLine = line;
101	      } else if (ch === '"' && field === "" && !wasQuoted) {
102	        inQuotes = true;
103	        wasQuoted = true;
104	        quoteLine = line;
105	        i += 1;
106	      } else {
107	        field += ch;
108	        i += 1;
109	      }
110	    }
111	
112	    if (inQuotes) {
113	      var err = new Error("Line " + quoteLine + ": a quoted value is never closed.");
114	      err.line = quoteLine;
115	      throw err;
116	    }
117	
118	    // Text that doesn't end in a newline still has a final record to flush.
119	    if (field !== "" || fields.length > 0 || wasQuoted) {
120	      endRecord();
121	    }
122	
123	    return records;
124	  }
125	
126	  /** Parse CSV text into an array of rows (arrays of strings). */
127	  function parseCSV(text) {
128	    return parseCSVRecords(text).map(function (r) { return r.fields; });
129	  }
130	
131	  function needsQuotes(s) {
132	    return /[",\r\n]/.test(s) || /^\s|\s$/.test(s);
133	  }
134	
135	  /** Turn one value into a CSV field, quoting only when needed. */
136	  function formatField(value) {
137	    var s = value == null ? "" : String(value);
138	    return needsQuotes(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
139	  }
140	
141	  /** Write rows (arrays of values) as CSV text with CRLF line endings. */
142	  function stringifyCSV(rows) {
143	    return (rows || []).map(function (row) {
144	      return row.map(formatField).join(",");
145	    }).join("\r\n") + ((rows || []).length ? "\r\n" : "");
146	  }
147	
148	  // ---- Spreadsheet safety ------------------------------------------------
149	  // A cell starting with = + - @ can run as a formula when the CSV is opened
150	  // in Excel / Sheets. On export, such text gets a leading apostrophe; on
151	  // import, that apostrophe is removed again so a round trip is lossless.
152	
153	  // Text that already starts with apostrophes before a formula character
154	  // gets one more, so it also survives the round trip unchanged.
155	
156	  var NEEDS_PROTECTION = /^'*[=+\-@\t\r]/;
157	  var IS_PROTECTED = /^'+[=+\-@\t\r]/;
158	
159	  function protectFormula(s) {
160	    return NEEDS_PROTECTION.test(s) ? "'" + s : s;
161	  }
162	
163	  function unprotectFormula(s) {
164	    return IS_PROTECTED.test(s) ? s.slice(1) : s;
165	  }
166	
167	  // ---- Expenses -> CSV ----------------------------------------------------
168	
169	  /** Export expenses (newest first) as CSV text with a header row. */
170	  function expensesToCSV(expenses) {
171	    var rows = [HEADER.slice()];
172	    L.sortNewestFirst(expenses || []).forEach(function (e) {
173	      rows.push([
174	        e.date,
175	        e.category,
176	        (L.toCents(e.amount) / 100).toFixed(2),
177	        protectFormula(e.note || "")
178	      ]);
179	    });
180	    return stringifyCSV(rows);
181	  }
182	
183	  // ---- CSV -> expenses ----------------------------------------------------
184	
185	  /**
186	   * Read an amount as written in a CSV cell. Accepts "12", "12.5", "12.50",
187	   * ".5" and "1,234.56" (thousands separators). Returns { value } or
188	   * { error }.
189	   */
190	  function parseAmount(raw) {
191	    var s = String(raw == null ? "" : raw).trim();
192	    if (s === "") return { error: "Amount is missing." };
193	
194	    var plain = /^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s) ? s.replace(/,/g, "") : s;
195	
196	    if (/^-\d*\.?\d+$/.test(plain)) {
197	      return { error: 'Amount "' + s + '" must be greater than 0.' };
198	    }
199	    if (!/^(\d+(\.\d*)?|\.\d+)$/.test(plain)) {
200	      return { error: 'Amount "' + s + '" is not a number.' };
201	    }
202	    if (/\.\d{3,}$/.test(plain)) {
203	      return { error: 'Amount "' + s + '" has more than 2 decimal places.' };
204	    }
205	    var value = Number(plain);
206	    if (!(value > 0)) {
207	      return { error: 'Amount "' + s + '" must be greater than 0.' };
208	    }
209	    return { value: value };
210	  }
211	
212	  function matchCategory(raw) {
213	    var s = String(raw == null ? "" : raw).trim().toLowerCase();
214	    for (var i = 0; i < L.CATEGORIES.length; i++) {
215	      if (L.CATEGORIES[i].toLowerCase() === s) return L.CATEGORIES[i];
216	    }
217	    return null;
218	  }
219	
220	  function isBlank(fields) {
221	    return fields.every(function (f) { return f.trim() === ""; });
222	  }
223	
224	  function listCategories() {
225	    var c = L.CATEGORIES;
226	    return c.slice(0, -1).join(", ") + " or " + c[c.length - 1];
227	  }
228	
229	  /**
230	   * Read expenses from CSV text.
231	   *
232	   * The first non-blank row must be a header naming the columns (any order,
233	   * any case): date, category, amount and optionally note. Blank rows are
234	   * skipped. Each bad row is reported and skipped; good rows are returned.
235	   *
236	   * Returns {
237	   *   expenses: [{ date, category, amount, note }],  // ready for createExpense
238	   *   errors:   [{ line, message }],                 // line is 1-based, or null
239	   *   rowCount: number of data rows read (good + bad)
240	   * }
241	   */
242	  function csvToExpenses(text) {
243	    var result = { expenses: [], errors: [], rowCount: 0 };
244	
245	    var records;
246	    try {
247	      records = parseCSVRecords(text);
248	    } catch (e) {
249	      result.errors.push({ line: e.line == null ? null : e.line, message: e.message });
250	      return result;
251	    }
252	
253	    records = records.filter(function (r) { return !isBlank(r.fields); });
254	    if (records.length === 0) {
255	      result.errors.push({ line: null, message: "The file is empty." });
256	      return result;
257	    }
258	
259	    // Header row -> column positions.
260	    var headerRec = records[0];
261	    var col = {};
262	    headerRec.fields.forEach(function (name, idx) {
263	      var key = name.trim().toLowerCase();
264	      if (key === "notes") key = "note";
265	      if (HEADER.indexOf(key) !== -1 && !(key in col)) col[key] = idx;
266	    });
267	    var missing = REQUIRED.filter(function (k) { return !(k in col); });
268	    if (missing.length) {
269	      result.errors.push({
270	        line: headerRec.line,
271	        message: "Missing column" + (missing.length > 1 ? "s" : "") + ": " +
272	          missing.join(", ") + ". The first row must be a header like: " + HEADER.join(",")
273	      });
274	      return result;
275	    }
276	
277	    function cell(fields, key) {
278	      return key in col && col[key] < fields.length ? fields[col[key]] : "";
279	    }
280	
281	    records.slice(1).forEach(function (rec) {
282	      result.rowCount += 1;
283	      var problems = [];
284	      var f = rec.fields;
285	
286	      var date = cell(f, "date").trim();
287	      if (!L.isValidDate(date)) {
288	        problems.push(date ? 'Date "' + date + '" is not a valid YYYY-MM-DD date.' : "Date is missing.");
289	      }
290	
291	      var rawCat = cell(f, "category");
292	      var category = matchCategory(rawCat);
293	      if (!category) {
294	        problems.push(rawCat.trim()
295	          ? 'Unknown category "' + rawCat.trim() + '" (use ' + listCategories() + ")."
296	          : "Category is missing.");
297	      }
298	
299	      var amount = parseAmount(cell(f, "amount"));
300	      if (amount.error) problems.push(amount.error);
301	
302	      if (problems.length) {
303	        result.errors.push({ line: rec.line, message: problems.join(" ") });
304	        return;
305	      }
306	
307	      var expense = {
308	        date: date,
309	        category: category,
310	        amount: amount.value,
311	        note: unprotectFormula(cell(f, "note").trim())
312	      };
313	      // Belt and braces: the app's own validation must agree.
314	      var errs = L.validateExpense(expense);
315	      var keys = Object.keys(errs);
316	      if (keys.length) {
317	        result.errors.push({ line: rec.line, message: keys.map(function (k) { return errs[k]; }).join(" ") });
318	        return;
319	      }
320	      result.expenses.push(expense);
321	    });
322	
323	    return result;
324	  }
325	
326	  return {
327	    HEADER: HEADER.slice(),
328	    parseCSV: parseCSV,
