356	    return el;
357	  }
358	
359	  function usedText(row) {
360	    if (row.budget == null) return "—";
361	    return row.percentLabel + (STATUS_WORD[row.status] ? " · " + STATUS_WORD[row.status] : "");
362	  }
363	
364	  function renderTableRow(row) {
365	    var tr = document.createElement("tr");
366	    if (row.status === B.STATUS.WARNING || row.status === B.STATUS.OVER) tr.className = "is-" + row.status;
367	    tr.appendChild(makeEl("td", null, row.category));
368	    tr.appendChild(makeEl("td", null, String(row.count)));
369	    tr.appendChild(makeEl("td", null, L.formatAmount(row.total)));
370	    tr.appendChild(makeEl("td", null, formatShare(row.share)));
371	    tr.appendChild(makeEl("td", null, row.budget == null ? "—" : L.formatAmount(row.budget)));
372	    tr.appendChild(makeEl("td", null, usedText(row)));
373	    return tr;
374	  }
375	
376	  function renderAlerts(report) {
377	    var rows = report.over.concat(report.warnings);
378	    var items = rows.map(function (row) {
379	      var li = makeEl("li", "budget-alert is-" + row.status);
380	      li.appendChild(statusIcon(row.status));
381	      li.appendChild(makeEl("span", null, alertText(row)));
382	      return li;
383	    });
384	    budgetAlertListEl.replaceChildren.apply(budgetAlertListEl, items);
385	    budgetAlertsEl.hidden = items.length === 0;
386	  }
387	
388	  function renderSummary() {
389	    var summary = L.summarizeMonth(expenses, selectedMonth);
390	    var report = B.budgetReport(summary, budgets);
391	    var hasData = summary.count > 0;
392	
393	    if (monthInput.value !== selectedMonth) monthInput.value = selectedMonth;
394	    monthInput.removeAttribute("aria-invalid");
395	
396	    monthLabelEl.textContent = formatMonthLabel(selectedMonth) + " total";
397	    monthTotalEl.textContent = L.formatAmount(summary.total);
398	    monthCountEl.textContent = "· " + plural(summary.count, "expense");
399	
400	    hideTooltip();
401	    // With budgets set, the chart is still useful for an empty month:
402	    // it shows each budget marker with nothing spent yet.
403	    var showChart = hasData || report.hasBudgets;
404	    summaryEmptyEl.hidden = hasData;
405	    chartEl.hidden = !showChart;
406	    tableViewEl.hidden = !showChart;
407	
408	    renderAlerts(report);
409	    barChartEl.replaceChildren.apply(barChartEl, report.categories.map(renderBarRow));
410	
411	    var rows = report.categories.map(renderTableRow);
412	    var foot = document.createElement("tr");
413	    foot.className = "table-total";
414	    foot.appendChild(makeEl("td", null, "Total"));
415	    foot.appendChild(makeEl("td", null, String(summary.count)));
416	    foot.appendChild(makeEl("td", null, L.formatAmount(summary.total)));
417	    foot.appendChild(makeEl("td", null, summary.total > 0 ? "100%" : "0%"));
418	    foot.appendChild(makeEl("td", null, report.hasBudgets ? L.formatAmount(report.budgetTotal) : "—"));
419	    // "Used" compares only the categories that have a budget.
420	    foot.appendChild(makeEl("td", null, report.hasBudgets
421	      ? B.percentLabel(report.budgetedSpent, report.budgetTotal) + " of budgeted"
422	      : "—"));
423	    rows.push(foot);
424	    summaryTableEl.replaceChildren.apply(summaryTableEl, rows);
425	  }
426	
427	  function setMonth(month) {
428	    if (!L.isValidMonth(month)) return;
429	    selectedMonth = month;
430	    renderSummary();
431	  }
432	
433	  // ---- Chart tooltip (hover + keyboard focus) -----------------------------
434	
435	  var activeRow = null;
436	
437	  function showTooltip(rowEl) {
438	    var row = rowEl.summaryRow;
439	    if (!row) return;
440	    if (activeRow) activeRow.classList.remove("is-active");
441	    activeRow = rowEl;
442	    rowEl.classList.add("is-active");
443	
444	    var lines = [
445	      makeEl("strong", null, row.category + " · " + L.formatAmount(row.total)),
446	      makeEl("span", null, formatShare(row.share) + " of the month · " + plural(row.count, "expense"))
447	    ];
448	    var bText = budgetText(row);
449	    if (bText) lines.push(makeEl("span", null, (STATUS_WORD[row.status] ? STATUS_WORD[row.status] + ": " : "") + bText));
450	    tooltipEl.replaceChildren.apply(tooltipEl, lines);
451	    tooltipEl.hidden = false;
452	
453	    // Anchor just past the end of the bar, above the row; keep it inside the chart.
454	    var track = rowEl.querySelector(".bar-track");
455	    var bar = rowEl.querySelector(".bar");
456	    var left = track.offsetLeft + (bar ? bar.offsetWidth : 0);
457	    var maxLeft = chartEl.clientWidth - tooltipEl.offsetWidth - 8;
458	    tooltipEl.style.left = Math.max(0, Math.min(left, maxLeft)) + "px";
459	    tooltipEl.style.top = (rowEl.offsetTop + 2) + "px";
460	  }
461	
462	  function hideTooltip() {
463	    if (activeRow) activeRow.classList.remove("is-active");
464	    activeRow = null;
465	    tooltipEl.hidden = true;
466	  }
467	
468	  function rowFromEvent(e) {
469	    return e.target.closest ? e.target.closest(".bar-row") : null;
470	  }
471	
472	  // ---- Form ---------------------------------------------------------------
473	
474	  function showErrors(errors) {
475	    Object.keys(fields).forEach(function (name) {
476	      var msg = errors[name] || "";
477	      document.getElementById(name + "-error").textContent = msg;
478	      if (msg) {
479	        fields[name].setAttribute("aria-invalid", "true");
480	      } else {
481	        fields[name].removeAttribute("aria-invalid");
482	      }
483	    });
484	  }
485	
486	  function readForm() {
487	    return {
488	      amount: amountInput.value,
489	      category: categoryInput.value,
490	      date: dateInput.value,
491	      note: noteInput.value
492	    };
493	  }
494	
495	  function resetForm() {
496	    amountInput.value = "";
497	    noteInput.value = "";
498	    // Keep the chosen category and date: handy when entering several at once.
499	    amountInput.focus();
500	  }
501	
502	  function onSubmit(event) {
503	    event.preventDefault();
504	    var input = readForm();
505	    var errors = L.validateExpense(input);
506	    showErrors(errors);
507	
508	    var firstBad = Object.keys(fields).find(function (n) { return errors[n]; });
509	    if (firstBad) {
510	      fields[firstBad].focus();
511	      return;
512	    }
513	
514	    var expense = L.createExpense(input, makeId(), Date.now());
515	    expenses = L.addExpense(expenses, expense);
516	    if (!saveExpenses(expenses)) {
517	      document.getElementById("note-error").textContent =
518	        "Added, but could not save to this browser's storage.";
519	    }
520	    render();
521	    resetForm();
522	  }
523	
524	  // ---- Budget form --------------------------------------------------------
525	
526	  function buildBudgetFields() {
527	    L.CATEGORIES.forEach(function (cat) {
528	      var id = "budget-" + cat.toLowerCase();
529	      var wrap = makeEl("div", "field budget-field");
530	
531	      var label = makeEl("label", null, cat);
532	      label.htmlFor = id;
533	
534	      var input = document.createElement("input");
535	      input.id = id;
536	      input.type = "number";
537	      input.inputMode = "decimal";
538	      input.min = "0";
539	      input.step = "0.01";
540	      input.placeholder = "No budget";
541	
542	      var err = makeEl("p", "error");
543	      err.id = id + "-error";
544	      err.setAttribute("role", "alert");
545	      input.setAttribute("aria-describedby", err.id);
546	
547	      input.addEventListener("input", function () {
548	        err.textContent = "";
549	        input.removeAttribute("aria-invalid");
550	        budgetSavedEl.textContent = "";
551	      });
552	
553	      wrap.appendChild(label);
554	      wrap.appendChild(input);
555	      wrap.appendChild(err);
556	      budgetFieldsEl.appendChild(wrap);
557	      budgetInputs[cat] = input;
558	      budgetErrors[cat] = err;
559	    });
560	  }
561	
562	  function fillBudgetFields() {
563	    L.CATEGORIES.forEach(function (cat) {
564	      var v = budgets[cat];
565	      budgetInputs[cat].value = v == null ? "" : (L.toCents(v) / 100).toFixed(2);
566	      budgetErrors[cat].textContent = "";
567	      budgetInputs[cat].removeAttribute("aria-invalid");
568	    });
569	  }
570	
571	  function onBudgetSubmit(event) {
572	    event.preventDefault();
573	    var next = {};
574	    var firstBad = null;
575	
576	    L.CATEGORIES.forEach(function (cat) {
577	      var input = budgetInputs[cat];
578	      // A number input with junk in it reports an empty value but bad validity.
579	      var raw = input.validity && input.validity.badInput ? "not a number" : input.value;
580	      var parsed = B.parseBudgetInput(raw);
581	      if (parsed.error) {
582	        budgetErrors[cat].textContent = parsed.error;
583	        input.setAttribute("aria-invalid", "true");
584	        if (!firstBad) firstBad = input;
585	      } else {
586	        budgetErrors[cat].textContent = "";
587	        input.removeAttribute("aria-invalid");
588	        next = B.setBudget(next, cat, parsed.value);
589	      }
590	    });
591	
592	    if (firstBad) {
593	      budgetSavedEl.textContent = "";
594	      firstBad.focus();
595	      return;
596	    }
597	
598	    budgets = next;
599	    budgetSavedEl.textContent = saveBudgets(budgets)
600	      ? "Budgets saved."
601	      : "Budgets applied, but could not be saved to this browser's storage.";
602	    fillBudgetFields();
603	    renderSummary();
604	  }
605	
606	  // ---- Init ---------------------------------------------------------------
607	
608	  L.CATEGORIES.forEach(function (cat) {
609	    var opt = document.createElement("option");
610	    opt.value = cat;
611	    opt.textContent = cat;
612	    categoryInput.appendChild(opt);
613	  });
614	
615	  dateInput.value = L.toISODate(new Date());
616	
617	  var expenses = loadExpenses();
618	  var budgets = loadBudgets();
619	
620	  buildBudgetFields();
621	  fillBudgetFields();
622	  budgetForm.addEventListener("submit", onBudgetSubmit);
623	
624	  form.addEventListener("submit", onSubmit);
625	
626	  // Clear a field's error as soon as the user edits it.
627	  Object.keys(fields).forEach(function (name) {
628	    fields[name].addEventListener("input", function () {
629	      document.getElementById(name + "-error").textContent = "";
630	      fields[name].removeAttribute("aria-invalid");
631	    });
632	  });
633	
634	  // Month picker. Browsers without <input type="month"> show a text box;
635	  // only a complete YYYY-MM value is accepted.
636	  function onMonthInput() {
637	    if (L.isValidMonth(monthInput.value)) {
638	      setMonth(monthInput.value);
639	    } else if (monthInput.value.length >= 7) {
640	      monthInput.setAttribute("aria-invalid", "true");
641	    }
642	  }
643	  monthInput.addEventListener("input", onMonthInput);
644	  monthInput.addEventListener("change", onMonthInput);
645	  monthInput.addEventListener("blur", function () {
646	    // Cleared or half-typed: put the selected month back.
647	    if (!L.isValidMonth(monthInput.value)) renderSummary();
648	  });
649	  prevMonthBtn.addEventListener("click", function () {
650	    setMonth(L.shiftMonth(selectedMonth, -1));
651	  });
652	  nextMonthBtn.addEventListener("click", function () {
653	    setMonth(L.shiftMonth(selectedMonth, 1));
654	  });
655	
656	  barChartEl.addEventListener("mouseover", function (e) {
657	    var row = rowFromEvent(e);
658	    if (row && row !== activeRow) showTooltip(row);
659	  });
660	  barChartEl.addEventListener("mouseleave", hideTooltip);
661	  barChartEl.addEventListener("focusin", function (e) {
662	    var row = rowFromEvent(e);
663	    if (row) showTooltip(row);
664	  });
665	  barChartEl.addEventListener("focusout", hideTooltip);
666	  barChartEl.addEventListener("keydown", function (e) {
667	    if (e.key === "Escape") hideTooltip();
668	  });
669	
670	  exportBtn.addEventListener("click", exportCsv);
671	  importInput.addEventListener("change", onImportFile);
672	
673	  // Stay in sync if the tracker is open in another tab.
674	  window.addEventListener("storage", function (e) {
675	    if (e.key === STORAGE_KEY) {
676	      expenses = loadExpenses();
677	      render();
678	    } else if (e.key === BUDGET_KEY) {
679	      budgets = loadBudgets();
680	      fillBudgetFields();
681	      renderSummary();
682	    }
683	  });
684	
685	  render();
686	})();
